const gitlinkOutputCheck: NativeCheckPlan = {
  id: 'gitlink-output',
  name: 'Read generated output in the child repository',
  executable: process.execPath,
  argv: [
    '-e',
    'if (require("node:fs").readFileSync("dist/output.txt", "utf8") !== "good") process.exit(1)',
  ],
  cwdRef: 'dependency',
  timeoutMs: 5_000,
  repeatable: true,
};

const roots: string[] = [];
afterEach(async () => {
  vi.restoreAllMocks();
  vi.unstubAllEnvs();
